1250	# =============================================================================
1251	GLOSSARY_MAX_CHARS=300
1252	
1253	validate_glossary() {
1254	    local kind msg
1255	    while IFS=$'\t' read -r kind msg; do
1256	        case "$kind" in
1257	            V) violations+=("$msg") ;;
1258	            W) warnings+=("$msg") ;;
1259	        esac
1260	    done < <(LC_ALL=C awk -v f="$FILE" -v max="$GLOSSARY_MAX_CHARS" '
1261	        function v(m) { printf "V\t%s:%d: %s\n", f, NR, m }
1262	        function w(m) { printf "W\t%s:%d: %s\n", f, NR, m }
1263	        # names compare as the drift check matches them: case and "-", "_", " " folded
1264	        function norm(x) { x = tolower(x); gsub(/[-_ ]+/, " ", x); gsub(/^ | $/, "", x); return x }
1265	        function claim(x, what) {
1266	            if (x == "") return
1267	            if (norm(x) in seen) v(what " \"" x "\" duplicates " seen[norm(x)] "; each term and alias names one entry")
1268	            else seen[norm(x)] = what " \"" x "\" (line " NR ")"
1269	        }
1270	        /^[[:space:]]*(```|~~~)/ { fence = !fence; prev = "other"; next }
1271	        fence { next }
1272	        /^# / {
1273	            if (!h1) { h1 = NR; if ($0 !~ /^# Glossary: [^[:space:]]/) w("the H1 is not \"# Glossary: <name>\"") }
1274	            prev = "other"; next
1275	        }
1276	        /^## / {
1277	            hd = $0; sub(/^## +/, "", hd); sub(/[[:space:]]+$/, "", hd)
1278	            if (hd == "Language") { if (lang_line) v("a second \"## Language\" section (the first is on line " lang_line ")"); else lang_line = NR; lang = 1 }
1279	            else lang = 0
1280	            prev = "other"; next
1281	        }
1282	        !lang_line && h1 && $0 ~ /[^[:space:]]/ { context = 1 }
1283	        !lang { prev = ($0 ~ /[^[:space:]]/) ? "other" : "blank"; next }
1284	        $0 !~ /[^[:space:]]/ { prev = "blank"; next }
1285	        /^### / { prev = "other"; next }
1286	        {
1287	            if ($0 ~ /(^|[^A-Za-z0-9_])[A-Za-z0-9_.~-]+\/[A-Za-z0-9_.-]/ || $0 ~ /\.(md|sh|bash|py|ts|js|json|jsonl|yaml|yml|toml|txt|bats|lock)([^A-Za-z0-9]|$)/)
1288	                w("a path or file extension; glossary definitions are implementation-free")
1289	        }
1290	        /^\*\*[^*]+\*\*: [^[:space:]]/ {
1291	            entries++
1292	            t = $0; sub(/^\*\*/, "", t); sub(/\*\*: .*$/, "", t); gsub(/`/, "", t); gsub(/^[[:space:]]+|[[:space:]]+$/, "", t)
1293	            claim(t, "term")
1294	            d = $0; sub(/^\*\*[^*]+\*\*: /, "", d); sub(/[[:space:]]+$/, "", d)
1295	            c = d; gsub(/[\200-\277]/, "", c)   # count characters, not UTF-8 continuation bytes
1296	            if (length(c) > max) v("the definition of \"" t "\" is " length(c) " characters, over " max "; shorten it")
1297	            s = d " "; n = gsub(/[.!?]+[)"]*[[:space:]]/, "&", s); if (n == 0) n = 1
1298	            if (n > 2) v("the definition of \"" t "\" has " n " sentences; at most two")
1299	            prev = "entry"; seen_avoid = 0; seen_alias = 0; next
1300	        }
1301	        /^_(Avoid|Aliases)_:/ {
1302	            k = ($0 ~ /^_Avoid_:/) ? "Avoid" : "Aliases"
1303	            if (prev != "entry" && prev != "annot") { v("_" k "_: is not directly after an entry; put it on the line below the **Term**: line"); prev = "other"; next }
1304	            if ((k == "Avoid" && seen_avoid) || (k == "Aliases" && seen_alias)) v("a second _" k "_: line for \"" t "\"; merge them")
1305	            if (k == "Avoid") seen_avoid = 1; else seen_alias = 1
1306	            a = $0; sub(/^_(Avoid|Aliases)_:[[:space:]]*/, "", a)
1307	            if (a !~ /[^[:space:]]/) v("an empty _" k "_: line")
1308	            if (k == "Aliases") {
1309	                gsub(/`/, "", a); m = split(a, parts, /,/)
1310	                for (i = 1; i <= m; i++) { p = parts[i]; gsub(/^[[:space:]]+|[[:space:]]+$/, "", p); claim(p, "alias") }
1311	            }
1312	            prev = "annot"; next
1313	        }
1314	        /^\*\*[^*]+\*\*:/ { v("an entry needs \"**Term**: definition\" with a space and text after the colon"); prev = "other"; next }
1315	        { v("a line in \"## Language\" that is not an entry, an _Avoid_:/_Aliases_: line or a ### heading; a definition stays on its entry line"); prev = "other" }
1316	        END {
1317	            NR = 1
1318	            if (!h1) v("no H1; start with \"# Glossary: <name>\"")
1319	            if (!lang_line) v("no \"## Language\" section")
1320	            else {
1321	                if (!context) v("no context paragraph between the H1 and \"## Language\"; say whose language this is in one paragraph")
1322	                if (!entries) v("\"## Language\" has no **Term**: entries")
1323	            }
1324	        }
1325	    ' "$FILE")
1326	    _md_pii_scan "a glossary is tracked prose, remove them"
1327	}
